import{z as B,x as n,o as t,c as d,q as i,j as o,D as e,d as l,s as A,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const P=JSON.parse('{"title":"边缘场与部分场","description":"","frontmatter":{"title":"边缘场与部分场","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/edge-field-partial.md","filePath":"litho/edge-field-partial.md","lastUpdated":1791413859000}'),p={name:"litho/edge-field-partial.md"};function h(m,a,C,D,f,u){const r=n("Mermaid");return t(),d("div",null,[a[2]||(a[2]=i('<h1 id="边缘场与部分场" tabindex="-1">边缘场与部分场 <a class="header-anchor" href="#边缘场与部分场" aria-label="Permalink to &quot;边缘场与部分场&quot;">​</a></h1><div class="epigraph"><p>圆晶圆上的矩形场在边缘被切成部分场：照明、调平、套刻采样和刻蚀负载同时换边界条件，场心模型不能外推到刀口。</p><footer>—— 对照晶圆边缘曝光、部分场与边缘良率的产线通称；[晶圆边缘曝光](/litho/wafer-edge-exposure) 已有轨道侧</footer></div><p><a href="/litho/metrology-matching">上一课</a>要求尺度可比。缺口是空间：边缘场、部分场（partial fields）常常不进抽样，却在探针图上先红。<a href="/litho/wafer-edge-exposure">边缘曝光</a> 与 EBR 已讲胶边；本课钉扫描机场被晶圆圆界切开时的成像与控制。应力翘曲如何整片弯网格，留给<a href="/litho/wafer-distortion-stress">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>部分场：曝光场只有一部分落在晶圆上。调平点缺失、狭缝平均被破坏、套刻标记可能落在场外、照明与散射边界改变。边缘完整场也有：薄膜卷曲、EBR、CMP 边缘侵蚀、卡盘边缘。良率图的「边缘环」常被当成脏，其实是控制盲区。</p><p><span class="marginnote">部分场（partial field）翻译过来很直白：曝光场是矩形，晶圆是圆的，最外圈的「场」被圆边切掉一角、只剩半块——这些残缺场就是部分场。场心处的所有模型与控制规律都不保证在刀口上仍成立。</span></p><p>缺口是<strong>把部分场当一等公民</strong>，不是再讲 EBR 涂胶。抽样计划若排除半径 &gt; 140 mm 的场，APC 的高阶项在边缘无约束，器件却在那里。</p><p><span class="marginnote">常见误区：良率图上发红的「边缘环」第一反应是「脏了、该清洗了」。很多时候那是控制盲区——调平、剂量与套刻在边缘都没有被真正测过与修正，问题随控制走，不随清洗走。</span></p><h3 id="产量与边缘的对赌" tabindex="-1">产量与边缘的对赌 <a class="header-anchor" href="#产量与边缘的对赌" aria-label="Permalink to &quot;产量与边缘的对赌&quot;">​</a></h3><p>多曝光一圈部分场增加管芯，也增加失控风险。策略：部分场用降阶校正、专用剂量/焦点偏置、或直接放弃最外环管芯。这是经济，不是光学失败。</p><p><span class="marginnote">对准只在内侧标记成功时，边缘场的网格是外推。外推距离应进套刻预算，而不是假装测过。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>计量：强制边缘/部分场进抽样子集。控制：边缘专用偏置或降阶；调平策略在缺点击时的回退。设计：边缘密封环、dummy。与缺陷：边缘剥落是检测重点，但不要和失焦 CD 混类。产量模型应把边缘管芯良率分开报。</p><p>部分场的曝光菜谱（叶片、剂量补偿）应单独验证，不要沿用完整场。晶圆边缘曝光课处理胶边；本课处理场被切开后的成像与网格。两者在最外环叠乘，Pareto 要能拆开。</p>',14)),(t(),o(s,null,{default:e(()=>[A(r,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20PF%5B%22%E6%9C%80%E5%A4%96%E7%8E%AF%E9%83%A8%E5%88%86%E5%9C%BA%22%5D%20--%3E%20Q%7B%22%E8%8F%9C%E8%B0%B1%E5%8F%AF%E5%8D%95%E7%8B%AC%E9%AA%8C%E8%AF%81%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E8%83%BD%22%7C%20BI%5B%22%E4%B8%93%E7%94%A8%E5%89%82%E9%87%8F%2F%E7%84%A6%E7%82%B9%E5%81%8F%E7%BD%AE%22%5D%0A%20%20Q%20--%3E%7C%22%E4%B8%8D%E8%83%BD%22%7C%20Q2%7B%22%E5%A5%97%E5%88%BB%E6%A0%87%E8%AE%B0%E5%8F%AF%E6%B5%8B%EF%BC%9F%22%7D%0A%20%20Q2%20--%3E%7C%22%E5%8F%AF%E6%B5%8B%22%7C%20RO%5B%22%E9%99%8D%E9%98%B6%E6%A8%A1%E5%9E%8B%E6%A0%A1%E6%AD%A3%22%5D%0A%20%20Q2%20--%3E%7C%22%E4%B8%8D%E5%8F%AF%E6%B5%8B%22%7C%20DROP%5B%22%E6%94%BE%E5%BC%83%E6%9C%80%E5%A4%96%E7%8E%AF%E7%AE%A1%E8%8A%AF%22%5D%0A%20%20BI%20--%3E%20Y%5B%22%E8%BE%B9%E7%BC%98%E7%AE%A1%E8%8A%AF%E8%89%AF%E7%8E%87%E5%8D%95%E7%8B%AC%E6%8A%A5%22%5D%0A%20%20RO%20--%3E%20Y%0A%20%20DROP%20--%3E%20Y%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[l("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"调平用若干点拟合平面/倾斜；缺点击时条件数变差，焦点残差升。照明在场被切时的散射与剂量积分变。刻蚀宏负荷在边缘开口率跳变。套刻高阶在边缘振幅最大，恰是点最少处——过拟合课的最坏布局。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"直觉类比：APC 用场内测到的点拟合一张「控制网」，边缘测点最少、偏移最大，网在那里只能悬空外推——就像只在城市中心设了气象站，却要预报海岸线的天气。这个「猜」的不确定性要单独记账。")],-1)),(t(),o(s,null,{default:e(()=>[A(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20EDGE%5B%22%E5%9C%86%E7%95%8C%20%2F%20%E9%83%A8%E5%88%86%E5%9C%BA%22%5D%20--%3E%20LVL%5B%22%E8%B0%83%E5%B9%B3%E7%82%B9%E7%BC%BA%E5%A4%B1%22%5D%0A%20%20EDGE%20--%3E%20SAMP%5B%22%E6%A0%87%E8%AE%B0%E5%8F%AF%E8%83%BD%E7%BC%BA%E5%A4%B1%22%5D%0A%20%20EDGE%20--%3E%20LOAD%5B%22%E8%B4%9F%E8%8D%B7%E4%B8%8E%E8%96%84%E8%86%9C%E8%B7%B3%E5%8F%98%22%5D%0A%20%20LVL%20--%3E%20RISK%5B%22%E8%BE%B9%E7%BC%98%E6%AE%8B%E5%B7%AE%22%5D%0A%20%20SAMP%20--%3E%20RISK%0A%20%20LOAD%20--%3E%20RISK%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=i('<p>调平点与标记在圆界上同时变少，网格变成外推。外推距离要进套刻预算，或明确放弃最外环管芯。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写某 300 mm 边缘排除半径的未公开规格。不重写 EBR 化学。High-NA 半场是另一类「部分」，不要混名。</p><p>后课默认：边缘与部分场要抽样、要降阶或专用偏置。下一课整片应力把网格弯成与边缘叠加的弯月。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>部分场改变调平、剂量积分与标记可测性，场心 APC 不能外推。</li><li>边缘应进入抽样，或明确放弃管芯。</li><li>外推网格要进套刻预算。</li><li>出处：晶圆边缘与 partial field 产线通称；ASML 调平/套刻公开讨论。</li></ul>',6))])}const _=B(p,[["render",h]]);export{P as __pageData,_ as default};
